BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
CREATE TEMP TABLE product_results(label text PRIMARY KEY,payload jsonb NOT NULL);
GRANT SELECT,INSERT ON product_results TO authenticated,service_role;
INSERT INTO auth.users(id,aud,role,email) VALUES
('33333333-3333-4333-8333-333333333333','authenticated','authenticated','product-one@example.invalid'),
('44444444-4444-4444-8444-444444444444','authenticated','authenticated','product-two@example.invalid');
SELECT set_config('request.jwt.claim.sub','',true);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
INSERT INTO product_results VALUES('settings',public.settings_get());
SELECT is((SELECT payload->>'timezone' FROM product_results WHERE label='settings'),'Etc/UTC','Settings default timezone is explicit UTC');
SELECT is((SELECT payload->>'reflection_enabled' FROM product_results WHERE label='settings'),'false','AI remains disabled');
INSERT INTO product_results VALUES('updated',public.settings_update('{"timezone":"Asia/Hong_Kong","voice":"mentor","memory_paused":true}',1));
SELECT is((SELECT payload->>'revision' FROM product_results WHERE label='updated'),'2','Settings update increments revision');
SELECT is((public.settings_get()->>'memory_paused'),'true','Memory preference persists');
SELECT throws_ok($$SELECT public.settings_update('{"voice":"friend"}',1)$$,'P0001','conflict','Stale preferences cannot overwrite newer revision');
SELECT throws_ok($$SELECT public.settings_update('{"reflection_enabled":true}',2)$$,'P0001','bad_request','Direct RPC cannot enable AI');
SELECT throws_ok($$SELECT public.settings_update('{"owner_id":"44444444-4444-4444-8444-444444444444"}',2)$$,'P0001','bad_request','Direct RPC rejects owner injection');
SELECT throws_ok($$SELECT public.settings_update('{"timezone":"Mars/Nowhere"}',2)$$,'P0001','bad_request','Invalid timezone rejected by database');
SELECT throws_ok($$SELECT public.settings_update('{"memory_paused":null}',2)$$,'P0001','bad_request','Null is not a memory preference');
SELECT throws_ok($$UPDATE public.user_settings SET voice='friend'$$,'42501',NULL,'Direct preference writes denied');
INSERT INTO product_results VALUES('entry',public.entry_create('Fictional source entry','55555555-5555-4555-8555-555555555555',false)->'entry');
INSERT INTO product_results VALUES('memory',public.memory_create('Fictional approved memory',(SELECT (payload->>'id')::uuid FROM product_results WHERE label='entry'),true,'66666666-6666-4666-8666-666666666666'));
SELECT is(public.memory_create('Fictional approved memory',(SELECT (payload->>'id')::uuid FROM product_results WHERE label='entry'),true,'66666666-6666-4666-8666-666666666666'),(SELECT payload FROM product_results WHERE label='memory'),'Memory retry is idempotent');
SELECT throws_ok($$SELECT public.memory_create('Changed payload',NULL,true,'66666666-6666-4666-8666-666666666666')$$,'P0001','conflict','Changed original approval conflicts');
SELECT throws_ok($$SELECT public.memory_create('Fictional memory',NULL,false,gen_random_uuid())$$,'P0001','bad_request','Approval is mandatory at DB boundary');
SELECT throws_ok($$SELECT public.memory_create(repeat(U&'\+01F600',1001),NULL,true,gen_random_uuid())$$,'P0001','bad_request','Memory bound counts UTF16 units');
SELECT ok(NOT ((SELECT payload FROM product_results WHERE label='memory') ?| ARRAY['owner_id','idempotency_key','original_payload']),'Memory resource excludes private metadata');
SELECT throws_ok($$SELECT original_payload FROM public.approved_memories$$,'42501',NULL,'Original memory payload cannot be read directly');
SELECT throws_ok($$INSERT INTO public.approved_memories(owner_id,idempotency_key) VALUES('33333333-3333-4333-8333-333333333333',gen_random_uuid())$$,'42501',NULL,'Direct memory writes denied');
INSERT INTO product_results VALUES('todo',public.todo_create('Fictional task','77777777-7777-4777-8777-777777777777'));
INSERT INTO product_results VALUES('todo_updated',public.todo_update((SELECT (payload->>'id')::uuid FROM product_results WHERE label='todo'),'{"completed":true,"title":"Edited task"}',1));
SELECT is((SELECT payload->>'revision' FROM product_results WHERE label='todo_updated'),'2','Todo revision increments');
SELECT is(public.todo_create('Fictional task','77777777-7777-4777-8777-777777777777'),(SELECT payload FROM product_results WHERE label='todo_updated'),'Creation replay returns edited todo');
SELECT throws_ok($$SELECT public.todo_update((SELECT (payload->>'id')::uuid FROM product_results WHERE label='todo'),'{"completed":false}',1)$$,'P0001','conflict','Stale todo edit rejected');
SELECT throws_ok($$SELECT public.todo_update((SELECT (payload->>'id')::uuid FROM product_results WHERE label='todo'),'{"completed":null}',2)$$,'P0001','bad_request','Null completed state rejected');
SELECT throws_ok($$SELECT public.todo_create(repeat(U&'\+01F600',1001),gen_random_uuid())$$,'P0001','bad_request','Todo bound counts UTF16 units');
SELECT throws_ok($$SELECT original_title FROM public.todos$$,'42501',NULL,'Original todo title is not user readable');
SELECT throws_ok($$SELECT public.account_delete_begin('44444444-4444-4444-8444-444444444444')$$,'42501',NULL,'Users cannot invoke privileged deletion queue or target other accounts');
SELECT throws_ok($$SELECT public.account_delete_claim(1)$$,'42501',NULL,'Users cannot claim cleanup jobs');
SELECT throws_ok($$SELECT * FROM private.account_deletions$$,'42501',NULL,'Private cleanup queue is unreadable');
SELECT is(jsonb_array_length(public.product_list('todos',1,NULL,NULL)),1,'Bounded todo list');
SELECT throws_ok($$SELECT public.product_list('profiles',1,NULL,NULL)$$,'P0001','bad_request','Table name injection rejected');
SELECT throws_ok($$SELECT public.product_list('todos',102,NULL,NULL)$$,'P0001','bad_request','Direct RPC page bounds enforced');
SELECT set_config('request.jwt.claims','{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM public.todos),0::bigint,'Todo RLS hides other owner');
SELECT is((SELECT count(*) FROM public.approved_memories),0::bigint,'Memory RLS hides other owner');
SELECT is((SELECT count(*) FROM public.user_settings),0::bigint,'Settings RLS hides other owner');
SELECT throws_ok($$SELECT public.product_get('todos',(SELECT (payload->>'id')::uuid FROM product_results WHERE label='todo'))$$,'P0001','not_found','Cross-owner todo read denied');
SELECT throws_ok($$SELECT public.product_delete('memories',(SELECT (payload->>'id')::uuid FROM product_results WHERE label='memory'))$$,'P0001','not_found','Cross-owner memory deletion denied');
SELECT throws_ok($$SELECT public.memory_create('Fictional stolen source',(SELECT (payload->>'id')::uuid FROM product_results WHERE label='entry'),true,gen_random_uuid())$$,'P0001','not_found','Memory cannot link another owners journal');
INSERT INTO product_results VALUES('other_todo',public.todo_create('Other users task',gen_random_uuid()));
SELECT set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
SELECT lives_ok($$SELECT public.entry_delete((SELECT (payload->>'id')::uuid FROM product_results WHERE label='entry'))$$,'Source entry deletion works');
SELECT throws_ok($$SELECT public.product_get('memories',(SELECT (payload->>'id')::uuid FROM product_results WHERE label='memory'))$$,'P0001','not_found','Source deletion removes linked memory');
SELECT lives_ok($$SELECT public.product_delete('todos',(SELECT (payload->>'id')::uuid FROM product_results WHERE label='todo'))$$,'Todo deletion works');
SELECT throws_ok($$SELECT public.todo_create('Fictional task','77777777-7777-4777-8777-777777777777')$$,'P0001','conflict','Deleted todo cannot be resurrected by retry');
RESET ROLE;
SELECT ok((SELECT text IS NULL AND original_payload IS NULL AND source_entry_id IS NULL FROM public.approved_memories WHERE id=(SELECT (payload->>'id')::uuid FROM product_results WHERE label='memory')),'Source-linked memory payload scrubbed');
SELECT ok((SELECT title IS NULL AND original_title IS NULL FROM public.todos WHERE id=(SELECT (payload->>'id')::uuid FROM product_results WHERE label='todo')),'Todo deletion scrubs both copies');
SET LOCAL ROLE service_role;
SELECT is(public.account_delete_begin('33333333-3333-4333-8333-333333333333'),' {"status":"deleting"}'::jsonb,'Privileged deletion begins atomically');
SELECT is(public.account_delete_begin('33333333-3333-4333-8333-333333333333'),' {"status":"deleting"}'::jsonb,'Repeated deletion request is safe');
INSERT INTO product_results VALUES('claim',public.account_delete_claim(1)->0);
SELECT is(jsonb_array_length(public.account_delete_claim(1)),0,'Active lease cannot be claimed twice');
SELECT throws_ok($$SELECT public.account_delete_purge('33333333-3333-4333-8333-333333333333',gen_random_uuid())$$,'P0001','conflict','Wrong fence cannot purge');
RESET ROLE;
UPDATE private.account_deletions SET lease_until=clock_timestamp()-interval '1 second' WHERE user_id='33333333-3333-4333-8333-333333333333';
SET LOCAL ROLE service_role;
INSERT INTO product_results VALUES('reclaim',public.account_delete_claim(1)->0);
SELECT isnt((SELECT payload->>'lease_token' FROM product_results WHERE label='claim'),(SELECT payload->>'lease_token' FROM product_results WHERE label='reclaim'),'Interrupted cleanup receives a new fence');
SELECT throws_ok($$SELECT public.account_delete_purge('33333333-3333-4333-8333-333333333333',(SELECT (payload->>'lease_token')::uuid FROM product_results WHERE label='claim'))$$,'P0001','conflict','Expired worker cannot purge');
SELECT is(public.account_delete_purge('33333333-3333-4333-8333-333333333333',(SELECT (payload->>'lease_token')::uuid FROM product_results WHERE label='reclaim')),true,'Current fence purges product content');
SELECT throws_ok($$SELECT public.account_delete_finish('33333333-3333-4333-8333-333333333333',(SELECT (payload->>'lease_token')::uuid FROM product_results WHERE label='reclaim'))$$,'P0001','conflict','Cleanup cannot finish before Auth deletion');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.todos WHERE owner_id='44444444-4444-4444-8444-444444444444'),1::bigint,'Other account survives cleanup');
SELECT is((SELECT count(*) FROM public.user_settings WHERE owner_id='33333333-3333-4333-8333-333333333333'),0::bigint,'Own settings purged');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
SELECT throws_ok($$SELECT public.settings_get()$$,'P0001','forbidden','Deleting user cannot recreate settings');
SELECT throws_ok($$SELECT public.todo_create('Cannot recreate',gen_random_uuid())$$,'P0001','forbidden','Deleting user cannot recreate todos');
SELECT is((SELECT count(*) FROM public.todos),0::bigint,'Deleting user has no direct product access');
RESET ROLE;
DELETE FROM auth.users WHERE id='33333333-3333-4333-8333-333333333333';
SET LOCAL ROLE service_role;
SELECT is(public.account_delete_purge('33333333-3333-4333-8333-333333333333',(SELECT (payload->>'lease_token')::uuid FROM product_results WHERE label='reclaim')),true,'Retry after Auth deletion is safe');
SELECT is(public.account_delete_finish('33333333-3333-4333-8333-333333333333',(SELECT (payload->>'lease_token')::uuid FROM product_results WHERE label='reclaim')),true,'Cleanup removes queue after Auth is gone');
RESET ROLE;
SELECT is((SELECT count(*) FROM private.account_deletions),0::bigint,'No finished account metadata retained');
SELECT * FROM finish();
ROLLBACK;
